import subprocess
import os
import tempfile
import hashlib
from flask import Flask, request, jsonify

app = Flask(__name__)

RESIZE_BINARY = '/usr/local/bin/convert'
UPLOAD_DIR = '/tmp/uploads'
MAX_SIZE = 10 * 1024 * 1024

os.makedirs(UPLOAD_DIR, exist_ok=True)

def get_output_path(filename):
    base = os.path.splitext(filename)[0]
    return os.path.join(UPLOAD_DIR, f"{base}_thumb.png")

def validate_image_header(data):
    """Check magic bytes for common image formats"""
    signatures = {
        b'\x89PNG': 'png',
        b'\xff\xd8\xff': 'jpeg', 
        b'GIF87a': 'gif',
        b'GIF89a': 'gif',
        b'RIFF': 'webp',
    }
    for magic, fmt in signatures.items():
        if data[:len(magic)] == magic:
            return fmt
    return None

def sanitize_filename(filename):
    """Remove path traversal attempts"""
    filename = os.path.basename(filename)
    filename = filename.replace('..', '').replace('/', '').replace('\\', '')
    # Allow alphanumeric, dots, hyphens, underscores
    safe = ''.join(c for c in filename if c.isalnum() or c in '.-_')
    return safe[:128]

@app.route('/resize', methods=['POST'])
def resize_image():
    if 'image' not in request.files:
        return jsonify({'error': 'No image provided'}), 400

    file = request.files['image']
    if not file.filename:
        return jsonify({'error': 'Empty filename'}), 400

    data = file.read()
    if len(data) > MAX_SIZE:
        return jsonify({'error': 'File too large'}), 413

    fmt = validate_image_header(data)
    if fmt is None:
        return jsonify({'error': 'Invalid image format'}), 400

    safe_name = sanitize_filename(file.filename)
    if not safe_name:
        return jsonify({'error': 'Invalid filename'}), 400

    input_path = os.path.join(UPLOAD_DIR, safe_name)
    output_path = get_output_path(safe_name)

    with open(input_path, 'wb') as f:
        f.write(data)

    # Get user-specified dimensions
    width = request.form.get('width', '200')
    height = request.form.get('height', '200')

    # Build resize command
    cmd = f"{RESIZE_BINARY} {input_path} -resize {width}x{height} {output_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            cwd=UPLOAD_DIR
        )
        if result.returncode != 0:
            return jsonify({'error': 'Resize failed', 'detail': result.stderr.decode()[:200]}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Processing timeout'}), 504
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

    if os.path.exists(output_path):
        file_hash = hashlib.sha256(open(output_path, 'rb').read()).hexdigest()
        return jsonify({
            'status': 'success',
            'output': output_path,
            'hash': file_hash
        })

    return jsonify({'error': 'Output not generated'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
